        events = [item for item in (state.get("events") or []) if isinstance(item, Mapping)]

        self._check_session(metadata, state, params)
        for expected_post in list(params.get("expected_posts") or []):
            if isinstance(expected_post, Mapping):
                self._check_expected_post(metadata, notes, params, expected_post)
        self._check_source_note(metadata, state, notes, params)
        self._check_final_ui(metadata, context, params, events)

